def diferenca(lista1, lista2):
    faltantes = []
    for lista in lista1:
        if lista not in lista2:
            faltantes.append(lista)
    return(faltantes)

def comparar(listas, nomes):
    for i in range(len(listas)):
        for j in range(i+1, len(listas)):
            print( nomes[i] + " tem a mais que " + nomes[j]+": ")
            print(len(diferenca(listas[i], listas[j])))
            print( nomes[j] + " tem a mais que " + nomes[i]+": ")
            print(len(diferenca(listas[j], listas[i])))

def diferencaMatrizes(matriz1, matriz2):
    cont = 0
    for i in range(len(matriz1)):
        for j in range(len(matriz1[i])):
            if matriz1[i][j] and not matriz2[i][j]:
                cont += 1
    return cont

def compararMatrizes(matrizes, nomes):
    for indice1 in range(len(matrizes)):
        for indice2 in range(indice1+1, len(matrizes)):
            print( nomes[indice1] + " tem a mais que " + nomes[indice2]+": ")
            print(diferencaMatrizes(matrizes[indice1], matrizes[indice2]))
            print( nomes[indice2] + " tem a mais que " + nomes[indice1]+": ")
            print(diferencaMatrizes(matrizes[indice2], matrizes[indice1]))

def uniao(listas):
    uniao = []
    for numLista in range(len(listas)):
        for lista in listas[numLista]:
            if lista not in uniao:
                uniao.append(lista)
    return(uniao)

def uniaoMatrizes(listas):
    uniao = [[ False for _ in range(12)] for _ in range(12)]
    for numMatriz in range(len(listas)):
        for matriz in listas:
            for i in range(len(matriz)):
                for j in range(len(matriz[i])):
                    if matriz[i][j] and not uniao[i][j]:
                        uniao[i][j] = True
    return(uniao)

def dominant(listas):
    dominantValues = set()
    for lista in listas:
        dominantValues.add(lista[0])
    return(dominantValues)

def relational(listas):
    matriz = [[ False for _ in range(12)] for _ in range(12)]
    for lista in listas:
        for i in range(len(lista)):
            for j in range(i+1, len(lista)):
                indice1 = lista[i]
                indice2 = lista[j]
                matriz[indice1][indice2] = True
    return matriz

def verificaTrue(matriz):
    cont = 0
    for i in range(len(matriz)):
        for j in range(len(matriz[i])):
            if matriz[i][j]:
                cont += 1
    return cont




        



